#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long steps = 0;
    long value = n;
    while (1) {
        if (value == 1) {
            printf("n=%ld steps=%ld\n", n, steps);
            break;
        }
        if (steps > 999999) {
            puts("STEP_LIMIT_EXCEEDED");
            break;
        }
        if (value > 1000000000000000L) {
            puts("OVERFLOW_GUARD");
            break;
        }
        if ((value & 1) == 0) {
            value = value >> 1;
        } else {
            value = value * 3 + 1;
        }
        steps++;
    }
    return 0;
}
